:root {
  --marca: #f5a524;
  --fondo: #ffffff;
  --texto: #1e2a5a;
  --pad: 8px;
}
.tarjeta {
  background: var(--fondo);
  color: var(--texto);
  padding: var(--pad);
  border: 2px solid var(--marca);
}
.promo { --marca: #e5484d; }

:root { --fondo: #ffffff; --texto: #1e2a5a; --acento: #b87710; }
@media (prefers-color-scheme: dark) {
  :root { --fondo: #1c1446; --texto: #ffffff; --acento: #ffc857; }
}
:root[data-tema="claro"]  { --fondo: #ffffff; --texto: #1e2a5a; --acento: #b87710; }
:root[data-tema="oscuro"] { --fondo: #1c1446; --texto: #ffffff; --acento: #ffc857; }
body { background: var(--fondo); color: var(--texto); }
a    { color: var(--acento); }

const lin = v => { v /= 255; return v <= 0.04045 ? v / 12.92 : ((v + 0.055) / 1.055) ** 2.4; };
const lum = hex => { const [r, g, b] = [1, 3, 5].map(i => lin(parseInt(hex.slice(i, i + 2), 16))); return 0.2126 * r + 0.7152 * g + 0.0722 * b; };
function contraste(a, b) { const x = lum(a), y = lum(b); return (Math.max(x, y) + 0.05) / (Math.min(x, y) + 0.05); }
const pares = [
  ['#000000', '#ffffff'],
  ['#767676', '#ffffff'],
  ['#777777', '#ffffff'],
  ['#ffffff', '#f5a524'],
  ['#2a1700', '#f5a524'],
];
for (const [t, f] of pares) {
  const r = contraste(t, f);
  console.log(`${t} sobre ${f}: ${r.toFixed(2)}  ${r >= 4.5 ? 'pasa AA texto normal' : r >= 3 ? 'solo texto grande o interfaz' : 'no pasa'}`);
}

@font-face {
  font-family: 'Jakarta';
  src: url('/fuentes/jakarta-400.woff2') format('woff2');
  font-weight: 400;
  font-display: swap;
}
body { font-family: 'Jakarta', system-ui, sans-serif; }

